            let div = document.createElement("div");
            div.innerHTML = `<div style="z-index:1000; position: fixed; bottom: 1rem; width: 100%; pointer-events:none;"><span style=" padding: 0.5rem; background: #ac2c2c; border-radius: 3px; color: white; pointer-events:auto;">error: ${event.data.status.replaceAll("_", " ")}</span></div>`;
            div = div.firstElementChild;
            document.body.appendChild(div);
            setTimeout(() => {
              div.remove();
            }, 1000*5);
          }
        }
        window.removeEventListener("message", messageHandler);
      } else if (event.data.type === "middleOut") {
        // the embed had to cut the middle out of the input to fit the context window. we warn here (not in the embed) because the generator's frame is the console that generator-builders (incl. the AI agent) can see.
        let d = event.data;
        let tokensInfo = d.originalTotalTokens ? ` (~${d.originalTotalTokens} -> ~${d.finalTotalTokens} tokens)` : ` (-> ~${d.finalTotalTokens} tokens)`;
        console.warn(`ai-text-plugin: The input (instruction + startWith) was longer than the AI model's context window allows (~${d.maxContextTokens} tokens max for the input), so the MIDDLE of the text was cut out ("middle-out" truncation) before it was sent to the AI: ${d.originalTotalChars} -> ${d.finalTotalChars} characters${tokensInfo}. The AI did not see the removed middle part. To avoid this, keep the input shorter - e.g. trim old chat/story history (keep only the most recent messages), summarize older history, or shorten long lore/instructions. Tip: if you imported this plugin as "ai", then ai({getMetaObject:true}).countTokens(text) gives an approximate token count.`);
      }
    }

    window.addEventListener("message", messageHandler);

    while(!window.__aiTextIframeEmbedIsReady) {
      await new Promise(r => setTimeout(r, 100));
    }
    if(inputData._debug) postData._debug = JSON.parse(JSON.stringify(inputData._debug));
